213	            output + static_cast<int64_t>(row) * n);
214	        const int active_groups = row / 4 + 1;
215	        const int first_group = part == 0 ? 0 : 1024;
216	        const int last_group = part == 0
217	            ? min(active_groups, 1024)
218	            : active_groups;
219	        for (int group = first_group + threadIdx.x; group < last_group;
220	             group += blockDim.x) {
221	            float4 value = source_row[group];
222	            if (group + 1 == active_groups) {
223	                const int valid = (row & 3) + 1;
224	                if (valid < 2) value.y = 0.0f;
225	                if (valid < 3) value.z = 0.0f;
226	                if (valid < 4) value.w = 0.0f;
227	            }
228	            output_row[group] = value;
229	        }
230	    }
