256	__global__ void convert_panel_kernel(
257	        const float* source, __half* compact, int rows, int leading) {
258	    constexpr int groups_per_row = 1024;
259	    const int64_t total = static_cast<int64_t>(rows) * groups_per_row;
260	    for (int64_t index = static_cast<int64_t>(blockIdx.x) * blockDim.x
261	             + threadIdx.x;
262	         index < total;
263	         index += static_cast<int64_t>(gridDim.x) * blockDim.x) {
264	        const int row = static_cast<int>(index >> 10);
265	        const int group = static_cast<int>(index & (groups_per_row - 1));
266	        const float4* source_row = reinterpret_cast<const float4*>(
267	            source + static_cast<int64_t>(row) * leading);
268	        const float4 value = source_row[group];
269	        const __half2 low = __floats2half2_rn(value.x, value.y);
270	        const __half2 high = __floats2half2_rn(value.z, value.w);
271	        const __half2_raw low_bits = static_cast<__half2_raw>(low);
272	        const __half2_raw high_bits = static_cast<__half2_raw>(high);
273	        uint2* destination = reinterpret_cast<uint2*>(
274	            compact + static_cast<int64_t>(row) * 4096);
275	        destination[group] = make_uint2(
276	            static_cast<unsigned>(low_bits.x) |
277	                (static_cast<unsigned>(low_bits.y) << 16),
278	            static_cast<unsigned>(high_bits.x) |
279	                (static_cast<unsigned>(high_bits.y) << 16));
280	    }
281	}
